def load_pristine_corpus():
    with open(os.path.join(WORK_DIR, "programme/zone_work_schedule.csv")) as f:
        zws = {r["zone_lift"]: r for r in csv.DictReader(f)}
    with open(os.path.join(WORK_DIR, "programme/activity_list.csv")) as f:
        acts = {r["activity_id"]: r for r in csv.DictReader(f)}
    with open(os.path.join(WORK_DIR, "programme/precedence_index.csv")) as f:
        prec = list(csv.DictReader(f))
    with open(os.path.join(WORK_DIR, "model/zone_schedule.csv")) as f:
        zones = {r["zone_id"]: r for r in csv.DictReader(f)}
    with open(os.path.join(WORK_DIR, "model/storey_schedule.csv")) as f:
