        crane_pos = {r["position_id"]: r for r in csv.DictReader(f)}
    with open(os.path.join(WORK_DIR, "site/crane_chart.csv")) as f:
        crane_chart = sorted([(float(r["radius_ft"]), float(r["rated_capacity_lb"])) for r in csv.DictReader(f)])
    with open(os.path.join(WORK_DIR, "catalogue/shoring_catalogue.csv")) as f:
        shoring_cat = {r["post_type"]: r for r in csv.DictReader(f)}
    with open(os.path.join(WORK_DIR, "catalogue/shoring_grid_options.csv")) as f:
        shoring_grids = set(float(r["spacing_ft"]) for r in csv.DictReader(f))
    with open(os.path.join(WORK_DIR, "catalogue/scaffold_catalogue.csv")) as f:
        scaf_cat = {r["system"]: r for r in csv.DictReader(f)}
    with open(os.path.join(WORK_DIR, "catalogue/scaffold_components.csv")) as f:
        scaf_comp = {r["component"]: r for r in csv.DictReader(f)}
    with open(os.path.join(WORK_DIR, "catalogue/scaffold_duty_classes.csv")) as f:
        scaf_duty = {r["duty_class"]: int(r["maximum_intended_load_lb_per_bay"]) for r in csv.DictReader(f)}
    with open(os.path.join(WORK_DIR, "catalogue/concrete_mix_schedule.csv")) as f:
        mixes = {r["mix_id"]: r for r in csv.DictReader(f)}
    with open(os.path.join(WORK_DIR, "rules/TWP-09_parameters.csv")) as f:
