    }

def verify_submission(corpus, seq_rows, stab_rows, occ_rows, tw_data, reg_rows, method_note_text):
    errors = []
    zws = corpus["zws"]
    acts = corpus["acts"]
    zones = corpus["zones"]
    slabs = corpus["slabs"]
    occ_below = corpus["occ"]

    # 1. Check all 294 activities present in construction_sequence.csv
    if len(seq_rows) != len(acts):
        errors.append(f"Expected {len(acts)} activities, got {len(seq_rows)}")
    seq_by_id = {r["activity_id"]: r for r in seq_rows}
    for aid, a in acts.items():
        if aid not in seq_by_id:
            errors.append(f"Missing activity {aid}")
            continue
        sr = seq_by_id[aid]
        dur = int(sr["duration_days"])
        s_day = int(sr["start_day"])
        f_day = int(sr["finish_day"])
        if dur != int(a["duration_days"]):
            errors.append(f"{aid}: duration {dur} != issued {a['duration_days']}")
        if f_day - s_day != dur:
            errors.append(f"{aid}: finish_day - start_day != duration_days")
        if s_day < 0:
            errors.append(f"{aid}: negative start_day {s_day}")

    # 2. Check all 308 precedence links
    for edge in corpus["prec"]:
        p_id = edge["predecessor"]
        s_id = edge["successor"]
        if int(seq_by_id[s_id]["start_day"]) < int(seq_by_id[p_id]["finish_day"]):
            errors.append(f"Precedence violated: {p_id} -> {s_id}")

    # 3. Check all 42 zone-lifts in temporary_works.json, stability_check.csv, occupancy_report.csv
    if not tw_data.get("designer") or not tw_data.get("drawing_reference"):
        errors.append("Missing designer or drawing_reference in temporary_works.json")
    tw_zls = tw_data.get("zone_lifts", {})
    stab_by_zl = {f"{r['level']}-{r['zone']}": r for r in stab_rows}
    occ_by_zl = {r["zone_lift"]: r for r in occ_rows}

    if len(tw_zls) != 42 or len(stab_by_zl) != 42 or len(occ_by_zl) != 42:
        errors.append(f"Expected 42 zone-lifts across files, got tw={len(tw_zls)}, stab={len(stab_by_zl)}, occ={len(occ_by_zl)}")

    act_by_zl = {}
    for sr in seq_rows:
        zl = f"{sr['level']}-{sr['zone']}"
        act_by_zl.setdefault(zl, {})[sr["activity_type"]] = sr

    for zl, zr in zws.items():
        lv = zr["level"]
        zn = zr["zone"]
        band = zn.split("-")[1]
        area = float(zr["area_sf"])
        face = float(zr["face_length_ft"])
        H_scaf = float(zr["scaffold_height_ft"])
        H_clear = float(zr["clear_height_ft"])
        pick = float(zr["heaviest_pick_lb"])
        wind_sf = float(zr["wind_exposed_sf"])
        lu = int(zr["laydown_units"])
        mix_id = zr["mix_id"]
        strike_days = int(corpus["mixes"][mix_id]["strike_days"])

        tw = tw_zls[zl]
        st = stab_by_zl[zl]
        oc = occ_by_zl[zl]
        za = act_by_zl[zl]

        # Check workspace_volume_cf (5% tolerance)
        base_w = float(tw["scaffold"]["base_width_ft"])
        for atype, sr in za.items():
            decl_vol = float(sr["workspace_volume_cf"])
            exp_vol = (face * base_w * H_scaf) if atype in ("SCAF", "SCST") else (area * H_clear)
            if abs(decl_vol - exp_vol) / exp_vol > 0.05:
                errors.append(f"{zl}.{atype}: workspace_volume_cf {decl_vol} vs {exp_vol}")

        # Check occupancy_report.csv exact match
        exp_occ_from = min(int(a["start_day"]) for a in za.values())
        exp_occ_to = max(int(a["finish_day"]) for a in za.values())
        exp_shor_from = int(za["SHOR"]["start_day"])
        exp_shor_to = int(za["STRK"]["finish_day"])
        exp_ch = sum(float(acts[a["activity_id"]]["crane_hours"]) for a in za.values())
        if int(oc["occupied_from_day"]) != exp_occ_from or int(oc["occupied_to_day"]) != exp_occ_to:
            errors.append(f"{zl}: occupied days mismatch in occupancy_report.csv")
        if int(oc["shored_from_day"]) != exp_shor_from or int(oc["shored_to_day"]) != exp_shor_to:
            errors.append(f"{zl}: shored days mismatch in occupancy_report.csv")
        if abs(float(oc["crane_hours_total"]) - exp_ch) > 0.02:
            errors.append(f"{zl}: crane_hours_total mismatch")
        if int(oc["laydown_units"]) != lu:
            errors.append(f"{zl}: laydown_units mismatch")

        # Check shoring
        sw_psf = float(slabs[(lv, zn)]["self_weight_psf"])
        ll_psf = 75.0 if band in ("E", "F", "G") else 50.0
        pd_psf = 15.0 if zl in occ_below else 0.0
        shor_psf = sw_psf + 10.0 + ll_psf + pd_psf
